//! Main row helpers defined beside the autogenerated `MainTraceRow` without touching
//! `traces.rs`: the number of execution steps a row packs, and the `IndexedFill` impls
//! the generic trace fillers are bound on.
//!
//! The compact *indexed* Main packing (a per-row instruction index plus one shared
//! instruction table, `MainTraceRowPackedIndexed` + `MainTraceRowInstrTable`) is not
//! available while a Main row carries more than one lane: `indexed_trace_row!` cannot
//! tag array columns as `@instr`, and the descriptor the unpacker consumes carries a
//! single index per row rather than one per lane. Bringing it back needs both a macro
//! and an unpacker change in pil2-proofman; until then every Main row type is a full
//! row and `IndexedFill::IS_INDEXED` stays `false` for all of them.

use proofman_fields::{Goldilocks, PrimeField64};

use crate::{MainTrace, MainTraceRow, MainTraceRowPacked};

/// Re-export so the emulator / main SM can bound generic fills on `zisk_pil::IndexedFill`.
pub use proofman_common::trace::IndexedFill;

// Derived from the autogenerated `MainTrace` alias, so they track the pilout — not hardcoded.
pub const MAIN_AIRGROUP_ID: usize = MainTrace::<()>::AIRGROUP_ID;
pub const MAIN_AIR_ID: usize = MainTrace::<()>::AIR_ID;

/// Execution steps packed into one Main row — `lanes_x_row` in main.pil.
///
/// Read off the generated row instead of being restated here, so it cannot drift from the
/// PIL: `flag` and `pc` are consecutive `[F; lanes_x_row]` columns of a `#[repr(C)]` struct
/// whose element is field-sized, so the gap between them is exactly one lane array.
pub const MAIN_LANES: usize = (std::mem::offset_of!(MainTraceRow<Goldilocks>, pc)
    - std::mem::offset_of!(MainTraceRow<Goldilocks>, flag))
    / std::mem::size_of::<Goldilocks>();

/// Execution steps one Main segment covers: every row of the air carries [`MAIN_LANES`] of
/// them. Segments are planned, chunked and range-checked in steps, not in rows.
pub const MAIN_STEPS_PER_SEGMENT: usize = MainTrace::<()>::NUM_ROWS * MAIN_LANES;

// The Main witness fill splits the trace into equal row ranges, one per minimal-trace chunk,
// which only tiles the air when the row count is a power of two.
const _: () = assert!(
    MainTrace::<()>::NUM_ROWS.is_power_of_two(),
    "MainTrace::NUM_ROWS must be a power of two",
);

impl<F: PrimeField64 + Copy + Default + Send + 'static> IndexedFill for MainTraceRow<F> {}
impl<F: PrimeField64 + Copy + Default + Send + 'static> IndexedFill for MainTraceRowPacked<F> {}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::MainTraceRowOps;

    #[test]
    fn main_lanes_matches_the_generated_row() {
        // `MAIN_LANES` is read off the row's memory layout; this pins it against the array
        // length the pil-helpers actually generated.
        let row = MainTraceRow::<Goldilocks>::default();
        assert_eq!(MAIN_LANES, row.pc.len());
        assert_eq!(MAIN_LANES, MainTraceRowOps::get_all_flag(&row).len());
    }
}
